#!/usr/bin/env bash
# ==============================================================================
# OzoneCast Studio - Synology DS720+ (DSM 7.2) One-Step Docker Installer
# ==============================================================================
set -e

TARGET_DIR="/volume1/docker/ozonecast"
echo "=========================================================="
echo " Deploying OzoneCast Studio to "
echo "=========================================================="

mkdir -p "/data"
chmod -R 775 ""

echo "[1/3] Extracting application files..."
PAYLOAD=""
echo "" | base64 -d | tar -xzf - -C ""
mkdir -p "/data"

cd ""
echo "[2/3] Building & starting Docker container on Synology DS720+..."
if docker compose version >/dev/null 2>&1; then
  docker compose build --no-cache
  docker compose up -d --force-recreate
elif command -v docker-compose >/dev/null 2>&1; then
  docker-compose build --no-cache
  docker compose up -d --force-recreate
else
  /var/packages/ContainerManager/target/usr/bin/docker compose build --no-cache
  /var/packages/ContainerManager/target/usr/bin/docker compose up -d --force-recreate
fi

NAS_IP=
echo "=========================================================="
echo " OzoneCast Studio is now running!"
echo " Open in browser (HTTP):  http://<YOUR-NAS-IP>:3080"
echo " Open in browser (HTTPS): https://<YOUR-NAS-IP>:3443"
echo "=========================================================="
